LEVEL = 1
CFG = {1: ("MIT", "Apache-2.0"), 2: ("GPL-3.0", "MIT"), 3: ("GPL-3.0", "Apache-2.0")}
COMPAT = {("MIT", "Apache-2.0"): True, ("GPL-3.0", "MIT"): False, ("GPL-3.0", "Apache-2.0"): True}
a, b = CFG[LEVEL]
key = (a, b) if (a, b) in COMPAT else (b, a)
print(a, "+", b, "->", "COMPATIBLE" if COMPAT.get(key) else "BLOCKED")

